type Decl = readonly [property: string, value: string]
interface Rule {
  selector: string
  decls: Decl[]
}
interface CssResult {
  decls: Decl[]
  rules?: Rule[]
  extra?: string
}

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max)
const round = (value: number, digits = 2) => Number(value.toFixed(digits))
const px = (n: number) => `${Math.round(n)}px`

function alpha(hex: string, opacity = 100): string {
  const match = /^#?([0-9a-f]{6})$/i.exec(hex.trim())
  if (!match) return hex
  const a = round(clamp(opacity, 0, 100) / 100)
  if (a >= 1) return `#${match[1].toLowerCase()}`
  const n = Number.parseInt(match[1], 16)
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`
}

const rgb = (hex: string) => {
  const n = Number.parseInt(hex.replace('#', '').slice(0, 6), 16) || 0
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}

function mix(a: string, b: string, t: number): string {
  const A = rgb(a)
  const B = rgb(b)
  return `#${A.map((v, i) =>
    Math.round(v + (B[i] - v) * t)
      .toString(16)
      .padStart(2, '0'),
  ).join('')}`
}

function readableOn(hex: string): string {
  const [r, g, b] = rgb(hex).map((v) => {
    const c = v / 255
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4
  })
  return 0.2126 * r + 0.7152 * g + 0.0722 * b > 0.4 ? '#000000' : '#ffffff'
}

function merge(...lists: Decl[][]): Decl[] {
  const map = new Map<string, string>()
  for (const list of lists) for (const [property, value] of list) map.set(property, value)
  return [...map]
}

const keyframes = (name: string, lines: string[]) =>
  `@keyframes ${name} {\n${lines.map((line) => `  ${line}`).join('\n')}\n}`
const reducedMotion = (body = 'animation: none;') =>
  `@media (prefers-reduced-motion: reduce) {\n  &,\n  &::before,\n  &::after {\n    ${body}\n  }\n}`
const rule = (selector: string, decls: Decl[]): Rule => ({ selector, decls })

/** `buttonEffectDefaults`, with the two kinds the demo shows. */
const BUTTON = {
  label: 'Get started',
  c1: '#6366f1',
  c2: '#ec4899',
  radius: 12,
  size: 15,
  speed: 3,
}

function buildButton(kind: 'glow' | 'shimmer'): CssResult {
  const s = BUTTON
  const base: Decl[] = [
    ['position', 'relative'],
    ['display', 'inline-flex'],
    ['align-items', 'center'],
    ['justify-content', 'center'],
    ['gap', '8px'],
    ['padding', `${px(s.size * 0.75)} ${px(s.size * 1.6)}`],
    ['font-family', 'inherit'],
    ['font-size', `${s.size}px`],
    ['font-weight', '600'],
    ['line-height', '1'],
    ['color', readableOn(s.c1)],
    ['border', 'none'],
    ['border-radius', `${s.radius}px`],
    ['cursor', 'pointer'],
    [
      'transition',
      'transform 0.2s ease, box-shadow 0.25s ease, background 0.25s ease, color 0.25s ease',
    ],
  ]
  const rules: Rule[] = []
  const extra: string[] = []
  let decls: Decl[]
  let hover: Decl[]
  const active: Decl[] = [['transform', 'scale(0.97)']]

  if (kind === 'glow') {
    decls = merge(base, [
      ['background', `linear-gradient(135deg, ${s.c1}, ${s.c2})`],
      ['box-shadow', `0 4px 14px ${alpha(s.c1, 35)}`],
      ['color', '#ffffff'],
    ])
    hover = [
      ['transform', 'translateY(-1px)'],
      ['box-shadow', `0 0 24px ${alpha(s.c1, 60)}, 0 0 48px ${alpha(s.c2, 35)}`],
    ]
  } else {
    decls = merge(base, [
      ['background', s.c1],
      ['overflow', 'hidden'],
    ])
    rules.push(
      rule('&::after', [
        ['content', '""'],
        ['position', 'absolute'],
        ['inset', '0'],
        [
          'background',
          `linear-gradient(110deg, transparent 30%, ${alpha('#ffffff', 45)} 50%, transparent 70%)`,
        ],
        ['transform', 'translateX(-100%)'],
        ['animation', `btn-shimmer ${s.speed}s ease-in-out infinite`],
        ['pointer-events', 'none'],
      ]),
    )
    hover = [['background', mix(s.c1, '#000000', 0.08)]]
    extra.push(
      keyframes('btn-shimmer', [
        '0% { transform: translateX(-100%); }',
        '60%, 100% { transform: translateX(100%); }',
      ]),
    )
  }

  rules.unshift(rule('&:hover', hover))
  rules.push(
    rule('&:active', active),
    rule('&:focus-visible', [
      ['outline', `2px solid ${s.c1}`],
      ['outline-offset', '3px'],
    ]),
  )
  if (extra.some((e) => e.startsWith('@keyframes'))) extra.push(reducedMotion())
  return { decls, rules, extra: extra.join('\n\n') || undefined }
}

const block = (selector: string, decls: Decl[]) =>
  `${selector} {\n${decls.map(([property, value]) => `  ${property}: ${value};`).join('\n')}\n}`

function supporting(result: CssResult, selector: string): string {
  const parts = (result.rules ?? [])
    .filter((r) => r.decls.length)
    .map((r) => block(r.selector.replaceAll('&', selector), r.decls))
  if (result.extra) parts.push(result.extra.replaceAll('&', selector))
  return parts.join('\n\n')
}

function toCss(result: CssResult, selector: string): string {
  const main = result.decls.length ? block(selector, result.decls) : ''
  return [main, supporting(result, selector)].filter(Boolean).join('\n\n')
}

function toTailwind(result: CssResult, selector: string): string {
  const classes = result.decls
    .map(([property, value]) => `[${property}:${value.replace(/_/g, '\\_').replace(/\s+/g, '_')}]`)
    .join(' ')
  const name =
    result.rules?.length || result.extra?.includes('&') ? `${selector.replace(/^\./, '')} ` : ''
  const code = `${name}${classes}`.trim()
  const rest = supporting(result, selector)
  return rest ? `${code}\n\n/* Add to your global CSS */\n${rest}` : code
}

function toSelector(name: string): string {
  const clean = name
    .trim()
    .replace(/^\.+/, '')
    .replace(/[^\w-]+/g, '-')
    .replace(/^-+|-+$/g, '')
  return clean ? `.${/^\d/.test(clean) ? `_${clean}` : clean}` : '.element'
}

const reactProperty = (property: string) =>
  property.startsWith('--')
    ? property
    : property
        .replace(
          /^-(webkit|moz)-/,
          (_, vendor: string) => `${vendor[0].toUpperCase()}${vendor.slice(1)}-`,
        )
        .replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase())

/** Declarations as a React style object, the way the live preview applies them. */
export const toStyle = (decls: Decl[]) =>
  Object.fromEntries(decls.map(([property, value]) => [reactProperty(property), value]))

/** `uiStyleDefaults`: liquid glass at 60% intensity and its 28px radius. */
function liquidGlass() {
  const i = 0.6
  const blur = `blur(${px(10 + 14 * i)}) saturate(180%)`
  const card: Decl[] = [
    ['position', 'relative'],
    ['padding', px(24)],
    ['border-radius', px(28)],
    [
      'background',
      `linear-gradient(135deg, ${alpha('#ffffff', Math.round(18 + 18 * i))}, ${alpha('#ffffff', Math.round(4 + 6 * i))})`,
    ],
    ['-webkit-backdrop-filter', blur],
    ['backdrop-filter', blur],
    ['border', `1px solid ${alpha('#ffffff', 45)}`],
    [
      'box-shadow',
      `inset 0 1px 0 ${alpha('#ffffff', 70)}, inset 0 -1px 0 ${alpha('#ffffff', 15)}, inset 0 0 ${px(12 + 16 * i)} ${alpha('#ffffff', 15)}, 0 12px 40px ${alpha('#0f172a', 25)}`,
    ],
    ['overflow', 'hidden'],
    ['isolation', 'isolate'],
    ['color', '#ffffff'],
  ]
  const before: Decl[] = [
    ['position', 'absolute'],
    ['inset', '0'],
    ['z-index', '-1'],
    ['border-radius', 'inherit'],
    ['background', `radial-gradient(120% 70% at 15% 0%, ${alpha('#ffffff', 45)}, transparent 55%)`],
    ['pointer-events', 'none'],
  ]
  const title: Decl[] = [
    ['margin', '0 0 6px'],
    ['font-size', '18px'],
    ['font-weight', '700'],
  ]
  const text: Decl[] = [
    ['margin', '0 0 16px'],
    ['font-size', '14px'],
    ['line-height', '1.5'],
    ['color', alpha('#ffffff', 85)],
  ]
  const button = merge(
    [
      ['display', 'inline-flex'],
      ['align-items', 'center'],
      ['justify-content', 'center'],
      ['padding', '10px 18px'],
      ['font-size', '14px'],
      ['font-weight', '600'],
      ['line-height', '1'],
    ],
    [
      ['background', `linear-gradient(180deg, ${alpha('#ffffff', 40)}, ${alpha('#ffffff', 12)})`],
      ['border', `1px solid ${alpha('#ffffff', 55)}`],
      ['border-radius', '999px'],
      ['box-shadow', `inset 0 1px 0 ${alpha('#ffffff', 80)}, 0 4px 12px ${alpha('#0f172a', 20)}`],
      ['color', '#ffffff'],
    ],
  )
  return {
    code: block('.element', card),
    card: toStyle(card),
    before: toStyle(before),
    title: toStyle(title),
    text: toStyle(text),
    button: toStyle(button),
  }
}
